abstract class PaymentProcessor {
  #balanceCents = 0;

  protected credit(amountCents: number): void {
    this.#balanceCents += amountCents;
  }

  get balanceCents(): number {
    return this.#balanceCents;
  }

  abstract charge(amountCents: number): Promise<void>;
}

class StripeProcessor extends PaymentProcessor {
  async charge(amountCents: number): Promise<void> {
    // appel réseau au fournisseur, puis mise à jour de l'état interne
    this.credit(amountCents);
  }
}

